def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the provided values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table with -inf
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N * 2 - 1)]

    # Base case
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for step in range(1, N * 2 - 1):
        for p1 in range(max(0, step - (N - 1)), min(step + 1, N)):
            p2 = step - p1
            if p2 >= N:
                continue
            val1 = grid[p1][step - p1]
            val2 = grid[p2][step - p2]
            if p1 > 0 and p2 > 0:
                dp[step][p1][p2] = max(dp[step][p1][p2], dp[step-1][p1-1][p2-1] + val1 + val2)
            if p1 > 0:
                dp[step][p1][p2] = max(dp[step][p1][p2], dp[step-1][p1-1][p2] + val1 + val2)
            if p2 > 0:
                dp[step][p1][p2] = max(dp[step][p1][p2], dp[step-1][p1][p2-1] + val1 + val2)
            dp[step][p1][p2] = max(dp[step][p1][p2], dp[step-1][p1][p2] + val1 + val2)

            # If both paths are at the same cell, subtract its value once
            if p1 == p2:
                dp[step][p1][p2] -= grid[p1][step - p1]

    return max(0, dp[N * 2 - 2][N - 1][N - 1])

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[0] * N for _ in range(N)] for _ in range(N)]

    for i in range(N):
        for j in range(N):
            for p in range(max(0, i+j-N+1), min(i+j+1, N)):
                q = i + j - p
                if p < 0 or q < 0 or p >= N or q >= N:
                    continue
                if i > 0 and p > 0:
                    dp[i][j][p] = max(dp[i][j][p], dp[i-1][j][p-1])
                if i > 0 and q > 0:
                    dp[i][j][p] = max(dp[i][j][p], dp[i-1][j][p])
                if j > 0 and p > 0:
                    dp[i][j][p] = max(dp[i][j][p], dp[i][j-1][p-1])
                if j > 0 and q > 0:
                    dp[i][j][p] = max(dp[i][j][p], dp[i][j-1][p])

                if i == p and j == q:
                    dp[i][j][p] += grid[i][j]
                else:
                    dp[i][j][p] += grid[i][j] + grid[p][q]

    return dp[N-1][N-1][N-1]

