def max_product(num_str: str, N: int, K: int) -> int:
    """
    Finds the maximum product that can be obtained by inserting K multiplication signs into the number string.

    :param num_str: A string representing the number string.
    :param N: An integer representing the length of the number string.
    :param K: An integer representing the number of multiplication signs to insert.
    :return: The maximum product that can be obtained.
    """
    def split_and_multiply(num_str, parts):
        if parts == 1:
            return int(num_str)

        max_product = 0
        for i in range(1, len(num_str) - parts + 2):
            left_part = int(num_str[:i])
            right_part_product = split_and_multiply(num_str[i:], parts - 1)
            max_product = max(max_product, left_part * right_part_product)

        return max_product

    return split_and_multiply(num_str, K + 1)

