def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    def count_separated_pairs(row_aisles, col_aisles):
        separated_count = 0
        for (x1, y1, x2, y2) in chatting_pairs:
            if (x1 < x2 and any(x1 < ra < x2 for ra in row_aisles)) or \
               (x1 > x2 and any(x2 < ra < x1 for ra in row_aisles)) or \
               (y1 < y2 and any(y1 < ca < y2 for ca in col_aisles)) or \
               (y1 > y2 and any(y2 < ca < y1 for ca in col_aisles)):
                separated_count += 1
        return separated_count

    best_row_aisles = []
    best_col_aisles = []
    best_count = 0

    for row_aisles in combinations(range(1, M), K):
        for col_aisles in combinations(range(1, N), L):
            separated_count = count_separated_pairs(row_aisles, col_aisles)
            if separated_count > best_count:
                best_count = separated_count
                best_row_aisles = row_aisles
                best_col_aisles = col_aisles

    return ' '.join(map(str, best_row_aisles)), ' '.join(map(str, best_col_aisles))

def count_passing_ways(n: int, m: int) -> int:
    MOD = 10**9 + 7

    # dp[i][j] will store the number of ways to reach student j after i passes
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1  # Starting point, one way to be at the starting student with 0 passes

    for i in range(1, m + 1):
        for j in range(n):
            # The ball can come to student j from j-1 or j+1 (considering the circle)
            dp[i][j] = (dp[i-1][(j-1) % n] + dp[i-1][(j+1) % n]) % MOD

    return dp[m][0] % MOD

def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1 if n == 1 else 0

    # dp[i][j] will store the number of ways to pass the ball to the i-th student in j passes
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1

    for k in range(1, m + 1):
        for i in range(n):
            left = (i - 1) % n
            right = (i + 1) % n
            dp[i][k] = dp[left][k - 1] + dp[right][k - 1]

    return dp[0][m]

