def count_partitions(n: int, k: int, x: int) -> int:
    def helper(n, k, x):
        if k == 1:
            return 1 if n >= x else 0
        if n < x * k or k < 1:
            return 0
        return helper(n - x, k - 1, x) + helper(n - 1, k, x + 1)

    return helper(n, k, x)

def count_partitions(n: int, k: int, x: int) -> int:
    # Base case: if n is less than k*x, it's not possible to partition n into k parts each at least x
    if n < k * x:
        return 0
    # Base case: if k is 1, there's only one way to partition n into one part
    if k == 1:
        return 1
    # Recursive case: sum the number of partitions by varying the first part from x to n-k*x+1
    return sum(count_partitions(n-i, k-1, i) for i in range(x, n-k*x+2))

def count_partitions(n: int, k: int, x: int) -> int:
    def helper(n, k, x, memo):
        if n == 0 and k == 0:
            return 1
        if n < 0 or k == 0:
            return 0
        if (n, k, x) in memo:
            return memo[(n, k, x)]

        count = 0
        for i in range(x, n - k + 2):
            count += helper(n - i, k - 1, i, memo)

        memo[(n, k, x)] = count
        return count

    memo = {}
    return helper(n, k, x, memo)

