def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a list to store the possible volumes that can be achieved
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: a volume of 0 can always be achieved with no items

    # Iterate over each item's volume
    for volume in volumes:
        # Update the dp array from back to front
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be achieved without exceeding V
    max_occupied_volume = 0
    for j in range(V + 1):
        if dp[j]:
            max_occupied_volume = j

    # The minimum remaining space is the total capacity minus the maximum occupied volume
    return V - max_occupied_volume

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array where dp[i] is True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # A subset with sum 0 is always possible (empty subset)

    # Iterate over each item volume
    for volume in volumes:
        # Traverse the dp array backwards to avoid using the same item multiple times
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be occupied which is less than or equal to V
    max_occupied_volume = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_occupied_volume = i
            break

    # The minimum remaining space is the difference between the box capacity and the max occupied volume
    return V - max_occupied_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, a[i - 1] + 1):
                if j >= k:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD
                else:
                    break

    return dp[n][m]

